def test_property_empty_is_utf8():
    m = from_bytes(b"")
    assert m.best().encoding == "utf_8"


def test_property_ascii():
    m = from_bytes(b"Hello World! The quick brown fox jumps over the lazy dog. " * 4)
    assert m.best().encoding == "ascii"


def test_property_type_error():
    try:
        from_bytes("not bytes")
    except TypeError:
        pass
    else:
        raise AssertionError("expected TypeError")


def test_property_matches_sorted():
    m = from_bytes("Bonjour monde, caf\u00e9".encode("utf-8") * 10)
    assert len(m) >= 1
    assert m.best() == m[0]


def test_differential_known_vectors():
    assert from_bytes(bytes.fromhex("48656c6c6f20576f726c6421")).best().encoding == "ascii"
    assert from_bytes(b"").best().encoding == "utf_8"
    assert from_bytes(bytes(range(256))).best() is None


def test_fuzz_bytes_never_raises():
    for n in [0, 1, 7, 64, 1024]:
        from_bytes(bytes((i * 31) & 0xFF for i in range(n)))


def test_identity_sensitive_repeats():
    a = b"Hello World!"
    b = bytes([72, 101, 108, 108, 111, 32, 87, 111, 114, 108, 100, 33])
    assert a == b and (a is not b)
    assert from_bytes(a).best().encoding == from_bytes(b).best().encoding


def test_is_binary_agrees():
    assert is_binary(b"Hello World!") is False
    assert is_binary(bytes(range(256))) is True

